    namespace f=thread_find_fixture;unsigned checks{},closed{};std::shared_ptr<ThreadFindBar> bar;f::ui::Panel host{nullptr};const auto check=[&](bool value,const char* why){++checks;if(!value)throw std::runtime_error(why);};
